/**
 * Generates a complete bipartite graph with the specified nodes.
 *
 * @param target the target graph to construct
 * @param resultMap a map to store the nodes with their corresponding coordinates
 */
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Initialize the graph with the correct number of nodes
    int numLeftNodes = (int) Math.floor(target.getNumNodes() / 2);
    int numRightNodes = target.getNumNodes() - numLeftNodes;
    target.addNodes(numLeftNodes, true, false);
    target.addNodes(numRightNodes, false, true);

    // Connect every left node to every right node
    for (int i = 0; i < numLeftNodes; i++) {
        for (int j = 0; j < numRightNodes; j++) {
            target.addEdge(target.getNode(i), target.getNode(i + numLeftNodes), 0, false, false);
        }
    }

    // Store the coordinates in the result map
    for (int i = 0; i < target.getNumNodes(); i++) {
        if (target.getNode(i).getLeft()) {
            resultMap.put(target.getNode(i).getId(), (V) 2*i/(numLeftNodes+1));
        } else {
            resultMap.put(target.getNode(i).getId(), (V) (1 + 2*i)/(numRightNodes+1));
        }
    }
}

