        // Calculate the year portion of the time bucket
        int yearPortion = (int) ((timeBucket / 100000000000L) % 10000L);

        // Compress the time bucket
        long compressedTimeBucket = yearPortion * 100000000000L + monthPortion * 100000000L + dayPortion;

