public static void writeUTF8(String str, WriteSession session, LinkedBuffer lb) {
    // Write the character encodings for each character in the string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            // Write 7-bit character
            lb.append((byte) c);
        } else if (c < 0x800) {
            // Write 2-byte character
            lb.append((byte)(0xc0 | (c >> 6)));
            lb.append((byte)(0x80 | (c & 0x3f)));
        } else if (c < 0xd800 || c >= 0xe000) {
            // Write 3-byte character
            lb.append((byte)(0xe0 | (c >> 12)));
            lb.append((byte)(0x80 | ((c >> 6) & 0x3f)));
            lb.append((byte)(0x80 | (c & 0x3f)));
        } else {
            // Write 4-byte character
            int codePoint = Character.codePointAt(str, i);
            i++;
            lb.append((byte)(0xf0 | (codePoint >> 18)));
            lb.append((byte)(0x80 | ((codePoint >> 12) & 0x3f)));
            lb.append((byte)(0x80 | ((codePoint >> 6) & 0x3f)));
            lb.append((byte)(0x80 | (codePoint & 0x3f)));
        }
    }
