private static String parsePlaceholders(String str, Properties props) {
    StringBuffer out = new StringBuffer();
    int i = 0;
    while (i < str.length()) {
        int start = str.indexOf("${", i);
        if (start == -1) {
            break;
        }
        out.append(str, i, start);
        int end = str.indexOf("}", start + 2);
        if (end == -1) {
            throw new IllegalArgumentException("Unterminated variable placeholder: " + str.substring(start));
        }
        String var = str.substring(start + 2, end);
        out.append(props.getProperty(var));
        i = end + 1;
    }
    out.append(str, i, str.length());
    return out.toString();
}
