public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("u cannot be null.");
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();

    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    int length = path.length();
    StringBuilder builder = new StringBuilder();
    boolean hasPathSegments = false;

    for (int i = 0; i < length; i++) {
        char c = path.charAt(i);

        if (c == '/') {
            if (hasPathSegments) {
                PathSegmentImpl segment = new PathSegmentImpl(builder.toString());
                pathSegments.add(segment);
                builder.setLength(0);
            }

            hasPathSegments = true;

            if (i < length - 1 && path.charAt(i + 1) != '/') {
                builder.append(c);
            }
