    // Check if the descriptor is a method descriptor
    if (descriptor.indexOf('(') != -1){
        // If it is, pop the argument types
        int numArgs = descriptor.indexOf(')') - descriptor.indexOf('(') - 1;
        for (int i = 0; i < numArgs; i++){
