private void pop(String descriptor) {

    // Assuming descriptor starts with a type descriptor
    if (descriptor.charAt(0) == 'L') {
      // If descriptor starts with a class descriptor (e.g. Ljava/lang/Object;),
      // pop the corresponding class object from the output frame stack
      popClass();
    } else {
      // If descriptor starts with a primitive descriptor (e.g. I),
      // pop the corresponding primitive value from the output frame stack
      switch (descriptor.charAt(0)) {
        case 'I':
          popInt();
          break;
        case 'J':
          popLong();
          break;
        case 'F':
          popFloat();
          break;
        case 'D':
          popDouble();
          break;
        case 'B':
          popByte();
          break;
        case 'C':
          popChar();
          break;
        case 'S':
          popShort();
          break;
        case 'Z':
          popBoolean();
          break;
        case 'V':
          pop(); // void
          break;
      }
    }
  }

