    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    while (true) {
        // Get the current node of the circulator
        Node cur = circ.getNode();

        // If the node satisfies the predicate, return it
        if (predicate.test(cur)) {
            return circ;
        }

        // If the current node is the stop node, wrap to the start node
        if (cur.equals(stop)) {
            circ.wrap(start);
        }

        // Advance the circulator in the opposite direction.
        // If the circulator reaches the start node, it means that the predicate is never met.
        // In this case, return the circulator.
        if (!circ.advanceMinus(dir)) {
            return circ;
        }
    }
