/**
* Checks the schema of the model to ensure that the sharding key indices are continuous.
*
* @param modelName the name of the model
* @throws IllegalStateException if sharding key indices are not continuous
*/
private void check(String modelName) throws IllegalStateException {
    // Get the schema of the model
    Schema schema = getSchema(modelName);

    // Get the sharding key indices of the model
    Set<Integer> shardingKeyIndices = getShardingKeyIndices(modelName);

    // Check if the sharding key indices are continuous
    if (!areShardingKeyIndicesContinuous(schema, shardingKeyIndices)) {
        throw new IllegalStateException("Sharding key indices are not continuous");
    }
}

/**
* Gets the schema of the model with the given name.
*
* @param modelName the name of the model
* @return the schema of the model
* @throws IllegalArgumentException if the model does not exist
*/
private Schema getSchema(String modelName) throws IllegalArgumentException {
    // Check if the model exists
    if (!modelExists(modelName)) {
        throw new IllegalArgumentException("Model does not exist");
    }

    // Get the schema of the model
    return SchemaRegistry.getSchema(modelName);
}

/**
* Gets the sharding key indices of the given model.
*
* @param modelName the name of the model
* @return the sharding key indices of the model
* @throws IllegalArgumentException if the model does not exist
*/
private Set<Integer> getShardingKeyIndices(String modelName) throws IllegalArgumentException {
    // Check if the model exists
    if (!modelExists(modelName)) {
        throw new IllegalArgumentException("Model does not exist");
    }

    // Get the sharding key indices of the model
    Set<Integer> shardingKeyIndices = new HashSet<Integer>();
    for (int i = 0; i < getSchema(modelName).getFields().size(); i++) {
        if (getSchema(modelName).getFields().get(i).isShardingKey()) {
            shardingKeyIndices.add(i);
        }
    }
    return shardingKeyIndices;
}

/**
* Checks if the sharding key indices of the given schema are continuous.
*
* @param schema the schema to check
* @param shardingKeyIndices the sharding key indices to check
* @return true if the sharding key indices are continuous, false otherwise
*/
private static boolean areShardingKeyIndicesContinuous(Schema schema, Set<Integer> shardingKeyIndices) {
    // Check if the sharding key indices are continuous
    int previousShardingKeyIndex = -1;
    for (Integer shardingKeyIndex : shardingKeyIndices) {
        if (previousShardingKeyIndex != -1 && shardingKeyIndex - previousShardingKeyIndex != 1) {
            return false;
        }
        previousShardingKeyIndex = shardingKeyIndex;
    }
    return true;
}

/**
* Checks if the given model exists.
*
* @param modelName the name of the model
* @return true if the model exists, false otherwise
*/
private boolean modelExists(String modelName) {
    return SchemaRegistry.containsSchema(modelName);
}

// This method checks the sharding key indices for the specified entity model.
public void check(String modelName) throws IllegalStateException {

if (shardingKeyIndices.isEmpty()) {
    // No sharding key indices are present, nothing to check
    return;
