    Map<String, Integer> refCounts = new HashMap<String, Integer>();
    for (SnapshotMetaData snapshotMetaData : snapshotMetaDatas) {
        for (String file : snapshotMetaData.files) {
            if (refCounts.get(file) == null) {
                refCounts.put(file, 0);
                continue;
            }
            refCounts.put(file, refCounts.get(file) + 1);
        }
    }
    for (IndexCommit commit : commits) {
        for (String file : commit.files()) {
            if (refCounts.get(file) == null) {
                refCounts.put(file, 0);
                continue;
            }
            refCounts.put(file, refCounts.get(file) - 1);
