public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize empty list to store suffix sums
    List<Integer> suffixSum = new ArrayList<>();
    // Initialize sum of all elements to 0
    long sum = 0;
    // Iterate over the list of bounds
    for (int i = 0; i < bounds.size(); i++) {
        // Get current bound
        int currentBound = bounds.get(i);
        // Compute suffix sum of current bound
        int suffixBound = currentBound;
        for (int j = i - 1; j >= 0; j--) {
            // If current bound exceeds previous bound, subtract previous bound from current bound
            if (suffixBound > bounds.get(j)) {
                suffixBound -= bounds.get(j);
            }
        }
        // Add suffix sum to list of suffix sums
        suffixSum.add(suffixBound);
        // Add current bound to sum of all elements
        sum += currentBound;
    }
    // Return pair of suffix sum list and sum of all elements
    return new Pair<>(suffixSum, sum);
}


