public static String base64Decode(String s) {
    // Check if the input string is empty
    if (s.isEmpty()) {
        return "";
    }

    // Check if the input string contains any non-Base64 characters
    if (!s.matches("[A-Za-z0-9+/=]*")) {
        throw new IllegalArgumentException("Input string contains non-Base64 characters");
    }

    // Initialize the output string
    String result = "";

    // Convert each base64 character to its corresponding byte value
    for (int i = 0; i < s.length(); i += 4) {
        byte b0 = (byte) (Character.digit(s.charAt(i), 64) << 2);
        byte b1 = (byte) ((Character.digit(s.charAt(i + 1), 64) & 0x30) >> 4);
        byte b2 = (byte) ((Character.digit(s.charAt(i + 2), 64) & 0x3C) >> 2);
        byte b3 = (byte) (Character.digit(s.charAt(i + 3), 64) & 0x3);

        result += (char) (b0 << 2 | b1 << 4 | b2 << 6);
        if (s.length() - i == 2) {
            result += (char) (b2 << 6);
        } else if (s.length() - i == 3) {
            result += (char) (b3 << 6);
        }
    }

    return result;
}
