 * @param source the source vertex of the edge
 * @param target the target vertex of the edge
 * @param edge the edge for which the minimal separators are to be computed
 * @return the list of minimal separators of the edge in the neighborhood of the edge
 */
private List<Pair<Integer, Integer>> computeSeparators(Integer source, Integer target, E edge){
    // initialize the list of minimal separators to be returned
    List<Pair<Integer, Integer>> separators = new List<>();

    // iterate over all vertices in the neighborhood of the edge
    for(Integer vertex : graph.neighbors(source)){
        // skip the target vertex
        if(vertex.equals(target)) {
            continue;
        }

        // get the list of edges incident to the current vertex
        List<E> incidentEdges = graph.edges(vertex);

        // iterate over all edges incident to the current vertex
        for(E incidentEdge : incidentEdges){
            // skip the edge itself
            if(incidentEdge.equals(edge)) {
                continue;
            }

            // compute the intersection of the edge and the incident edge
            Pair<Double, Double> intersection = getIntersection(edge, incidentEdge);

            // if the intersection point is not empty, add it to the list of separators
            if(!intersection.isEmpty()){
                separators.add(new Pair<>(vertex, incidentEdge));
