    Integer vertex21 = graph.getSource(edge2);
    Integer vertex22 = graph.getTarget(edge2);

    // compute the intersection point
    Pair<Double, Double> intersection;
    if(Math.signum(vertex11 - vertex21) != Math.signum(vertex12 - vertex21)){
        // the edges do not overlap and share only one endpoint
        intersection = new Pair<>(Double.NaN, Double.NaN);
    } else if(Math.signum(vertex11 - vertex21) == 0){
