        intersection = new Pair<>(vertex11, vertex12);
    } else if(Math.signum(vertex11 - vertex21) != 0){
        // the edges do not share any endpoints, but they overlap
        intersection = new Pair<>(vertex11, vertex12);
    } else{
        // the edges overlap and share two endpoints
        intersection = new Pair<>(vertex11, vertex12);
    }

    return intersection;
}

