private List<Pair<Integer, Integer>> computeMinimalSeparators(E edge) {
    // Initialize the list of minimal separators
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

    // Iterate over all vertices in the edge
    for (V vertex : edge.getVertices()) {
        // Compute the degree of the vertex
