private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // check if the given vertices form a complete subgraph
    Set<E> edges = new HashSet<>();
    for (V u : vertices) {
        for (V v : vertices) {
            if (u != v) {
                E edge = graph.getEdge(u, v);
                if (edge == null) {
                    return false;
                }
                edges.add(edge);
            }
        }
    }
    // check if the induced subgraph is a clique
    return edges.size() == vertices.size() * (vertices.size() - 1) / 2;
}

