/**
* Pops as many abstract types from the output frame stack as described by the given descriptor.
*
* @param descriptor a type or method descriptor (in which case its argument types are popped).
*/
private void pop(String descriptor) {
    // Get the number of types in the descriptor
    int numTypes = descriptor.length();

    // Loop through the descriptor and pop each type from the output frame stack
    for (int i = 0; i < numTypes; i++) {
        char type = descriptor.charAt(i);

        // Handle type descriptor characters
        switch (type) {
            case 'B': // Byte
            case 'C': // Char
            case 'D': // Double
            case 'F': // Float
            case 'I': // Int
            case 'J': // Long
            case 'S': // Short
            case 'Z': // Boolean
                popByte();
                break;
            case 'L': // Reference type
                popReference();
                break;
            case '[': // Array type
                popArray();
                break;
            case '(': // Method type
                popMethod();
                break;
            default:
                throw new IllegalArgumentException("Unsupported type descriptor: " + type);
        }
    }
}

